        : width(width), height(height), tileSize(tileSize), memoryUsage(memoryUsage) {}

    void generateTerrain(int playerX, int playerZ, int radius) {
        std::vector<std::thread> threads;
        std::mutex mtx;
        std::condition_variable cv;

        for (int x = playerX - radius; x <= playerX + radius; ++x) {
