    private static class TerrainTask extends RecursiveAction {
        private final float[][] terrain;
        private final int startX, endX, startY, endY;

        public TerrainTask(float[][] terrain, int startX, int endX, int startY, int endY) {
            this.terrain = terrain;
            this.startX = startX;
            this.endX = endX;
            this.startY = startY;
            this.endY = endY;
        }

        @Override
        protected void compute() {
            if (endX - startX <= 10 && endY - startY <= 10) {
                // Base case: generate terrain directly
