#include "Engine.h"
#include "Materials/MaterialInstanceConstant.h"
#include "Components/StaticMeshComponent.h"

void renderRoadTexture(UStaticMeshComponent* meshComponent, UMaterialInterface* material) {
    // Ensure the material is set on the mesh component
    meshComponent->SetMaterial(0, material);

    // Enable texture streaming
    if (UMaterialInstanceConstant* materialInstance = Cast<UMaterialInstanceConstant>(material)) {
        materialInstance->SetScalarParameterValue(TEXT("TextureStreaming"), 1.0f);
    }

    // Enable virtual texturing
    if (UMaterialInstanceConstant* materialInstance = Cast<UMaterialInstanceConstant>(material)) {
        materialInstance->SetScalarParameterValue(TEXT("VirtualTexturing"), 1.0f);
    }

    // Set LOD bias
    if (UMaterialInstanceConstant* materialInstance = Cast<UMaterialInstanceConstant>(material)) {
        materialInstance->SetScalarParameterValue(TEXT("LODBias"), 1.0f);
    }

    // Set LOD distance
