                if (VehiclePosition.X >= i * totalLength && VehiclePosition.X < (i + 1) * totalLength) {
                    totalVehicles++;
                    totalSpeed += VehicleSpeed;
                }
            }
        }

        if (totalVehicles > 0) {
            road_network.traffic_flow_patterns[i].density = totalVehicles / totalLength;
            road_network.traffic_flow_patterns[i].speed = totalSpeed / totalVehicles;
            road_network.traffic_flow_patterns[i].flow = road_network.traffic_flow_patterns[i].density * road_network.traffic_flow_patterns[i].speed;
        } else {
            road_network.traffic_flow_patterns[i].density = 0.0f;
            road_network.traffic_flow_patterns[i].speed = 50.0f;
            road_network.traffic_flow_patterns[i].flow = 0.0f;
