// Function to calculate Bezier curve points
FVector CalculateBezierPoint(const FVector* control_points, int num_control_points, float t) {
    FVector result = FVector::ZeroVector;
    for (int i = 0; i < num_control_points; i++) {
        float binomial = FMath::BinomialCoefficient(num_control_points - 1, i);
        float term = binomial * FMath::Pow(t, i) * FMath::Pow(1 - t, num_control_points - 1 - i);
        result += term * control_points[i];
    }
    return result;
}

