} VertexPool;

VertexPool* create_vertex_pool(size_t capacity) {
    VertexPool* pool = (VertexPool*)malloc(sizeof(VertexPool));
    pool->data = (Vertex*)malloc(capacity * sizeof(Vertex));
    pool->capacity = capacity;
    pool->size = 0;
    return pool;
}

void destroy_vertex_pool(VertexPool* pool) {
    free(pool->data);
    free(pool);
}

Vertex* allocate_vertex(VertexPool* pool) {
    if (pool->size >= pool->capacity) {
        printf("Vertex pool overflow\n");
        exit(1);
    }
    return &pool->data[pool->size++];
}

