```cpp
#include "PxPhysicsAPI.h"
#include "PxDefaultErrorCallback.h"
#include "PxPvd.h"
#include "PxPvdTransport.h"
#include "PxProfileZoneManager.h"

class PhysicsPipeline {
private:
    PxPhysics* m_physics;
    PxDefaultErrorCallback m_errorCallback;
    PxFoundation* m_foundation;
    PxPvd* m_pvd;
    PxScene* m_scene;

public:
    PhysicsPipeline() {
        // Create the foundation
        m_foundation = PxCreateFoundation(PX_PHYSICS_VERSION, m_errorCallback, nullptr);

        // Create the physics SDK
        PxTolerancesScale scale;
        m_physics = PxCreatePhysics(PX_PHYSICS_VERSION, *m_foundation, scale, true, m_pvd);

        // Enable the visual debugger if needed
        if (m_pvd) {
            m_pvd->connect(PVD_HOST, 5425, 10);
        }

        // Create the scene
        PxSceneDesc sceneDesc(m_physics->getTolerancesScale());
        sceneDesc.gravity = PxVec3(0.0f, -9.81f, 0.0f);
        sceneDesc.cpuDispatcher = PxDefaultCpuDispatcherCreate(4); // Adjust based on available cores
        sceneDesc.filterShader = PxDefaultSimulationFilterShader;
        sceneDesc.flags |= PxSceneFlag::eENABLE_CCD; // Enable continuous collision detection
        sceneDesc.broadPhaseType = PxBroadPhaseType::eMBP; // Use MBP for better performance
        sceneDesc.solverType = PxsSolverType::eTGS; // Use TGS solver for better performance
        m_scene = m_physics->createScene(sceneDesc);

        // Create the vehicle
        PxRigidDynamic* vehicle = PxCreateDynamic(*m_physics, PxTransform(PxVec3(0.0f, 1.0f, 0.0f)), PxBoxGeometry(2.0f, 1.0f, 5.0f), *m_physics->createMaterial(0.5f, 0.5f, 0.5f), 1.0f);
        vehicle->setMass(1000.0f); // Set the mass of the vehicle
        vehicle->setAngularDamping(0.5f); // Set angular damping
        vehicle->setLinearVelocity(PxVec3(10.0f, 0.0f, 0.0f)); // Set initial linear velocity
        m_scene->addActor(*vehicle);

        // Create the ground
        PxRigidStatic* ground = PxCreateStatic(*m_physics, PxTransform(PxVec3(0.0f, -1.0f, 0.0f)), PxBoxGeometry(100.0f, 1.0f, 100.0f));
        m_scene->addActor(*ground);

        // Create an obstacle
        PxRigidStatic* obstacle = PxCreateStatic(*m_physics, PxTransform(PxVec3(0.0f, 1.0f, 0.0f)), PxBoxGeometry(2.0f, 2.0f, 2.0f));
        m_scene->addActor(*obstacle);
    }

    ~PhysicsPipeline() {
        if (m_scene) {
            m_scene->release();
        }
        if (m_physics) {
            m_physics->release();
        }
        if (m_foundation) {
            m_foundation->release();
        }
    }

    void update(float deltaTime) {
        // Update physics simulation
        m_scene->simulate(deltaTime);
        m_scene->fetchResults(true);
    }
};
```

