#### 1. Define the Vehicle Structure

First, define the structure of your vehicle, including the wheels and suspension.

```cpp
class Vehicle {
private:
    PxPhysics* m_physics;
    PxScene* m_scene;
    PxRigidDynamic* vehicleActor;
    PxMaterial* material;
    PxWheelShape* frontLeftWheel;
    PxWheelShape* frontRightWheel;
    PxWheelShape* rearLeftWheel;
    PxWheelShape* rearRightWheel;

public:
    Vehicle(PxPhysics* physics, PxScene* scene) : m_physics(physics), m_scene(scene) {
        // Initialize PhysX
        PxInitExtensions();

        // Create a material with appropriate friction and restitution
        material = m_physics->createMaterial(0.5f, 0.5f, 0.5f); // Adjust values as needed

        // Create a vehicle actor
        vehicleActor = PxCreateDynamic(*m_physics, PxTransform(PxVec3(0, 1, 0)), 
                                       PxBoxGeometry(PxVec3(1, 1, 1)), *material, 1500.0f);

        // Set initial velocity
        vehicleActor->setLinearVelocity(PxVec3(10.0f, 0.0f, 0.0f));

        // Add the vehicle actor to the scene
        m_scene->addActor(*vehicleActor);

        // Create wheels
        createWheels();
    }

    ~Vehicle() {
        if (vehicleActor) {
            m_scene->removeActor(*vehicleActor);
            vehicleActor->release();
        }
        if (material) {
            material->release();
        }
        if (frontLeftWheel) {
            frontLeftWheel->release();
        }
        if (frontRightWheel) {
            frontRightWheel->release();
        }
        if (rearLeftWheel) {
            rearLeftWheel->release();
        }
        if (rearRightWheel) {
            rearRightWheel->release();
        }
    }

    void createWheels() {
        // Define wheel properties
        PxVec3 wheelSize(0.5f, 0.5f, 0.5f);
        float wheelWidth = 0.2f;
        float wheelRadius = 0.5f;
        float wheelSuspensionLength = 0.5f;
        float wheelMaxSuspensionTravel = 1.0f;
        float wheelSpringStrength = 1000.0f;
        float wheelDamperStrength = 20.0f;

        // Create front left wheel
        frontLeftWheel = PxCreateWheelShape(*m_physics, wheelSize, wheelWidth, wheelRadius, wheelSuspensionLength, wheelMaxSuspensionTravel, wheelSpringStrength, wheelDamperStrength);
        frontLeftWheel->setLocalPose(PxTransform(PxVec3(-1.0f, 1.0f, 1.0f)));
        vehicleActor->attachShape(*frontLeftWheel);

        // Create front right wheel
        frontRightWheel = PxCreateWheelShape(*m_physics, wheelSize, wheelWidth, wheelRadius, wheelSuspensionLength, wheelMaxSuspensionTravel, wheelSpringStrength, wheelDamperStrength);
        frontRightWheel->setLocalPose(PxTransform(PxVec3(1.0f, 1.0f, 1.0f)));
        vehicleActor->attachShape(*frontRightWheel);

        // Create rear left wheel
        rearLeftWheel = PxCreateWheelShape(*m_physics, wheelSize, wheelWidth, wheelRadius, wheelSuspensionLength, wheelMaxSuspensionTravel, wheelSpringStrength, wheelDamperStrength);
        rearLeftWheel->setLocalPose(PxTransform(PxVec3(-1.0f, .0f, -1.0f)));
        vehicleActor->attachShape(*rearLeftWheel);

        // Create rear right wheel
        rearRightWheel = PxCreateWheelShape(*m_physics, wheelSize, wheelWidth, wheelRadius, wheelSuspensionLength, wheelMaxSuspensionTravel, wheelSpringStrength, wheelDamperStrength);
        rearRightWheel->setLocalPose(PxTransform(PxVec3(1.0f, 1.0f, -1.0f)));
        vehicleActor->attachShape(*rearRightWheel);
    }
};
```

### Key Points

1. **Wheel Properties**:
   - Define the size, width, radius, and suspension properties of the wheels.
   - Adjust these properties to match the desired behavior of the vehicle.

2. **Attaching Wheels**:
   - Attach the wheels to the vehicle actor using `attachShape`.
   - Set the local pose of each wheel to place it correctly on the vehicle.

3. **Suspension Properties**:
   - Define the spring strength, damper strength, and maximum suspension travel to control how the vehicle responds to bumps and uneven terrain.

