public:
    PhysicsSystem()
    {
        PxProfileZoneManager* profileZoneManager = NULL;
        PxProfileZone* profileZone = NULL;

        PxProfileZoneManagerDesc profileZoneManagerDesc;
        profileZoneManager = PxProfileZoneManagerFactoryCreate(profileZoneManagerDesc);

        PxProfileZoneDesc profileZoneDesc;
        profileZoneDesc.name = "MyProfileZone";
        profileZone = profileZoneManager->createProfileZone(profileZoneDesc);

        PxProfileZoneSet(profileZone);

        PxDefaultErrorCallback errorCallback;
        PxDefaultAllocator allocator;
        PxFoundation foundation(errorCallback, allocator);

        PxPhysics* physics = PxCreatePhysics(PX_PHYSICS_VERSION, foundation, PxTolerancesScale(), true, profileZone);

        if (!physics)
        {
            UE_LOG(LogTemp, Error, TEXT("Failed to initialize PhysX SDK"));
            return;
        }

        PxPvd* pvd = physics->createPvd();
        if (pvd)
        {
            pvd->connect(PVD_HOST, 5425, 10);
        }

        PxSceneDesc sceneDesc(physics->getTolerancesScale());
        sceneDesc.gravity = PxVec3(0.0f, -9.81f, 0.0f);
        PxScene* scene = physics->createScene(sceneDesc);

        if (!scene)
        {
            UE_LOG(LogTemp, Error, TEXT("Failed to create PhysX scene"));
            return;
        }

        PxMaterial* defaultMaterial = physics->createMaterial(0.5f, 0.5f, 0.5f);
        if (!defaultMaterial)
        {
            UE_LOG(LogTemp, Error, TEXT("Failed to create PhysX material"));
            return;
        }

        // Store references to the created objects
        Physics = physics;
        Scene = scene;
        DefaultMaterial = defaultMaterial;
    }

    ~PhysicsSystem()
    {
        if (DefaultMaterial)
        {
            DefaultMaterial->release();
        }

        if (Scene)
        {
            Scene->release();
        }

        if (Physics)
        {
            Physics->release();
        }

        if (ProfileZone)
        {
            ProfileZoneManager->destroyProfileZone(ProfileZone);
        }

        if (ProfileZoneManager)
        {
            PxProfileZoneManagerFactoryDestroy(ProfileZoneManager);
        }
    }

private:
    PxPhysics* Physics = nullptr;
    PxScene* Scene = nullptr;
    PxMaterial* DefaultMaterial = nullptr;
    PxProfileZoneManager* ProfileZoneManager = nullptr;
    PxProfileZone* ProfileZone = nullptr;
};
