#include "Engine.h"

AMyCustomActor::AMyCustomActor()
{
    PrimaryActorTick.bCanEverTick = true;
    PrimaryActorTick.TickGroup = TG_PrePhysics;
    TargetTickRate = 120.0f; // Hz
    TickInterval = 1.0f / TargetTickRate; // Seconds per tick
}

void AMyCustomActor::BeginPlay()
{
    Super::BeginPlay();
    LastTickTime = GetWorld()->GetTimeSeconds();
}

void AMyCustomActor::Tick(float DeltaTime)
{
    Super::Tick(DeltaTime);

    // Measure elapsed time since the last tick
    float CurrentTime = GetWorld()->GetTimeSeconds();
    float ElapsedTime = CurrentTime - LastTickTime;

    // Update simulation state
