    // Calculate the remaining sleep time to cap the tick rate
    float SleepTime = FMath::Max(0.0f, TickInterval - ElapsedTime);

    // Update the last tick time
    LastTickTime = CurrentTime;

    // Sleep if necessary
    if (SleepTime > .001f) // Avoid very short sleeps
    {
        FPlatformProcess::Sleep(SleepTime);
    }
}

