#include <stdio.h>
#include <stdlib.h>

typedef struct Cell {
    int x, y;
} Cell;

typedef struct Quadtree {
    int x, y, width, height;
    struct Quadtree* nw, *ne, *sw, *se;
    int num_cells;
    Cell* cells;
} Quadtree;

Quadtree* create_quadtree(int x, int y, int width, int height) {
    Quadtree* quadtree = malloc(sizeof(Quadtree));
    quadtree->x = x;
    quadtree->y = y;
    quadtree->width = width;
    quadtree->height = height;
    quadtree->nw = NULL;
    quadtree->ne = NULL;
    quadtree->sw = NULL;
    quadtree->se = NULL;
    quadtree->num_cells = 0;
    quadtree->cells = NULL;
    return quadtree;
}

void free_quadtree(Quadtree* quadtree) {
    if (quadtree == NULL) return;
    free_quadtree(quadtree->nw);
    free_quadtree(quadtree->ne);
    free_quadtree(quadtree->sw);
    free_quadtree(quadtree->se);
    free(quadtree->cells);
    free(quadtree);
}

void insert_cell(Quadtree* quadtree, Cell* cell) {
    if (quadtree->num_cells < 10) { // Threshold for splitting
        quadtree->cells = realloc(quadtree->cells, (quadtree->num_cells + 1) * sizeof(Cell));
        quadtree->cells[quadtree->num_cells++] = *cell;
        return;
    }

    if (quadtree->nw == NULL) {
        int half_width = quadtree->width / 2;
        int half_height = quadtree->height / 2;
        quadtree->nw = create_quadtree(quadtree->x, quadtree->y, half_width, half_height);
        quadtree->ne = create_quadtree(quadtree->x + half_width, quadtree->y, half_width, half_height);
        quadtree->sw = create_quadtree(quadtree->x, quadtree->y + half_height, half_width, half_height);
        quadtree->se = create_quadtree(quadtree->x + half_width, quadtree->y + half_height, half_width, half_height);

        for (int i = 0; i < quadtree->num_cells; i++) {
            insert_cell(quadtree, &quadtree->cells[i]);
        }
        free(quadtree->cells);
        quadtree->cells = NULL;
        quadtree->num_cells = 0;
    }

    if (cell->x < quadtree->x + quadtree->width / 2) {
        if (cell->y < quadtree->y + quadtree->height / 2) {
            insert_cell(quadtree->nw, cell);
        } else {
            insert_cell(quadtree->sw, cell);
        }
    } else {
        if (cell->y < quadtree->y + quadtree->height / 2) {
            insert_cell(quadtree->ne, cell);
        } else {
            insert_cell(quadtree->se, cell);
        }
    }
}

void query_cells(Quadtree* quadtree, int x, int y, int width, int height, Cell** result, int* count) {
    if (quadtree == NULL) return;

