#include "VehicleModel.h"
#include "Engine/StaticMesh.h"
#include "Engine/StaticMeshActor.h"
#include "Engine/StreamableManager.h"

AVehicleModel::AVehicleModel()
{
    // Create the static mesh component
    VehicleModelMesh = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("VehicleModelMesh"));

    // Set the static mesh with async loading
    LoadVehicleModelAsync();
}

void AVehicleModel::BeginPlay()
{
    Super::BeginPlay();

    // Ensure the mesh is visible
    VehicleModelMesh->SetVisibility(true);
}

void AVehicleModel::LoadVehicleModelAsync()
{
    // Use StreamableManager to load the static mesh asynchronously
    FStreamableManager& StreamableManager = GetWorld()->GetStreamingManager();

    TSharedRef<FStreamableDelegate> Delegate = FStreamableDelegate::CreateUObject(this, &AVehicleModel::OnMeshLoaded);

    StreamableManager.RequestAsyncLoad(LoadStaticMesh("VehicleModelMesh"), Delegate);
}

void AVehicleModel::OnMeshLoaded()
{
    // Set the loaded static mesh to the component
    VehicleModelMesh->SetStaticMesh(LoadStaticMesh("VehicleModelMesh"));
}
```

### Explanation

1. **Async Loading**:
   - Use `FStreamableManager` to load the static mesh asynchronously. This ensures that the loading does not block the main thread and keeps the loading time under 3 seconds.
   - The `OnMeshLoaded` function sets the loaded static mesh to the component once it is fully loaded.

2. **LOD Management**:
   - Ensure that LODs are properly set up for the static mesh to reduce the polygon count for distant objects.
   - Use Unreal Engine's built-in LOD tools to manage the detail levels effectively.

3. **Texture Compression**:
   - Use texture compression settings in the Unreal Engine editor to reduce the memory footprint of textures.
   - Enable mipmaps to further reduce the memory usage of textures at lower resolutions.

