#include "Math/Plane.h"

void CalculateFrustumPlanes(const APlayerController* PlayerController, TArray<FPlane>& FrustumPlanes)
{
    if (!PlayerController || !PlayerController->GetPawn())
    {
        return;
    }

    const FVector ViewLocation = PlayerController->GetPawn()->GetActorLocation();
    const FRotator ViewRotation = PlayerController->GetPawn()->GetActorRotation();
    const FMatrix ViewMatrix = FMatrix::MakeIdentity();
    const float AspectRatio = PlayerController->AspectRatio;
    const float FOV = PlayerController->FOVAngle;
    const float NearClip = PlayerController->NearClipPlane;
    const float FarClip = PlayerController->FarClipPlane;

    FFrustumBuilder::BuildFrustum(FrustumPlanes, ViewMatrix, AspectRatio, FOV, NearClip, FarClip);
}
```

#### 2. Check Object Visibility

Next, check if an object is within the view frustum by testing its bounding box against the frustum planes.

```cpp
bool IsObjectVisible(const FBox& ObjectBounds, const TArray<FPlane>& FrustumPlanes)
{
    for (const FPlane& Plane : FrustumPlanes)
    {
        if (FMath::SegmentPlaneIntersection(ObjectBounds.Min, ObjectBounds.Max, Plane) == EIntersectionResult::No)
        {
            return false;
        }
    }
    return true;
}
```

#### 3. Render Only Visible Objects

Finally, render only the objects that are within the view frustum.

