}

void Vehicle::Update(float deltaTime) {
    // Update speed
    if (currentSpeed < maxSpeed) {
        currentSpeed += acceleration * deltaTime;
    } else if (currentSpeed > 0) {
        currentSpeed -= deceleration * deltaTime;
    }

    // Update chassis position
    PxVec3 chassisPosition = chassis->getGlobalPose().p;
    chassisPosition.z += currentSpeed * deltaTime;
    chassis->setGlobalPose(PxTransform(chassisPosition));

    // Update wheels
    for (PxRigidDynamic* wheel : wheels) {
        wheel->setGlobalPose(PxTransform(wheel->getGlobalPose().p + PxVec3(0, 0, currentSpeed * deltaTime)));
    }

    // Update steering angle
    steeringAngle += 0.1f * deltaTime;  // Example steering input
    for (PxRigidDynamic* wheel : wheels) {
        wheel->setGlobalPose(PxTransform(wheel->getGlobalPose().p, PxQuat(PxPi * steeringAngle / 180.0f, PxVec3(0, 1, 0))));
    }

    // Update suspension
    for (PxRigidDynamic* wheel : wheels) {
        PxVec3 wheelPosition = wheel->getGlobalPose().p;
        wheelPosition.y += suspensionCompression * deltaTime;
        wheel->setGlobalPose(PxTransform(wheelPosition, wheel->getGlobalPose().q));
    }
}
