#include "GameFramework/Actor.h"
#include <vector>
#include <memory>

// Define the octree node structure
struct OctreeNode
{
    std::shared_ptr<OctreeNode> children[8];  // Child nodes
    std::vector<int> data;                    // Data stored in this node (for leaf nodes)

    bool IsLeaf() const
    {
        return std::all_of(std::begin(children), std::end(children), [](const auto& child) { return !child; });
    }

    void InsertData(int x, int y, int z, int value)
    {
        if (IsLeaf())
        {
            data.push_back(value);
        }
        else
        {
            int index = ((x & 1) << 2) | ((y & 1) << 1) | (z & 1);
            if (!children[index])
            {
                children[index] = std::make_shared<OctreeNode>();
            }
            children[index]->InsertData(x >> 1, y >> 1, z >> 1, value);
        }
    }

    std::vector<int> QueryData(int x, int y, int z)
    {
        if (IsLeaf())
        {
            return data;
        }

        int index = ((x & 1) << 2) | ((y & 1) << 1) | (z & 1);
        if (children[index])
        {
            return children[index]->QueryData(x >> 1, y >> 1, z >> 1);
        }
        return {};
    }
};

// Define the environment actor
class AEnvironmentActor : public AActor
{
public:
    AEnvironmentActor()
    {
        // Initialize the octree root node
        OctreeRoot = std::make_shared<OctreeNode>();
    }

    void AddTerrainCell(int x, int y, int z, int value)
    {
        // Convert grid cell coordinates to octree node coordinates
        int octreeX = x >> 3;  // Assuming 8x8x8 cells per octree node
        int octreeY = y >> 3;
        int octreeZ = z >> 3;

        // Insert data into the octree
        OctreeRoot->InsertData(octreeX, octreeY, octreeZ, value);
    }

    std::vector<int> QueryTerrainCells(int x, int y, int z)
    {
        // Convert grid cell coordinates to octree node coordinates
        int octreeX = x >> 3;  // Assuming 8x8x8 cells per octree node
        int octreeY = y >> 3;
        int octreeZ = z >> 3;

        // Query data from the octree
        return OctreeRoot->QueryData(octreeX, octreeY, octreeZ);
    }

private:
    std::shared_ptr<OctreeNode> OctreeRoot;
};

// Example usage
int main()
{
    AEnvironmentActor environmentActor;

    // Add terrain cells to the octree
    for (int i = 0; i < 50000; ++i)
    {
        int x = rand() % 1000;
        int y = rand() % 1000;
        int z = rand() % 1000;
        int value = rand() % 100;
        environmentActor.AddTerrainCell(x, y, z, value);
    }

    // Query terrain cells from the octree
    int x = 500;
    int y = 500;
    int z = 500;
    std::vector<int> queriedData = environmentActor.QueryTerrainCells(x, y, z);

    // Output the queried data
    for (int value : queriedData)
    {
        std::cout << "Queried value: " << value << std::endl;
    }

    return 0;
}
```

### Explanation

1. **Octree Node Structure**:
   - `OctreeNode` is a structure that holds either data (for leaf nodes) or references to child nodes (for non-leaf nodes).

2. **Insert Data**:
   - The `InsertData` method inserts data into the octree. If the current node is a leaf, it stores the data directly. Otherwise, it recursively inserts the data into the appropriate child node.

3. **Query Data**:
   - The `QueryData` method retrieves data from the octree based on the provided coordinates. It traverses the tree to find the appropriate leaf node and returns the stored data.

4. **Grid to Octree Conversion**:
   - The `AddTerrainCell` method converts grid cell coordinates to octree node coordinates and inserts the data into the octree.
   - The `QueryTerrainCells` method converts grid cell coordinates to octree node coordinates and queries the data from the octree.

