// Helper function to determine if an object is visible
bool IsObjectVisible(const glm::vec3& objectPosition, const glm::vec3& cameraPosition, const glm::vec3& cameraDirection, float farPlane)
{
    // Calculate the distance between the object and the camera
    float distance = glm::distance(objectPosition, cameraPosition);

    // Calculate the dot product of the camera direction and the object direction
    float dotProduct = glm::dot(cameraDirection, glm::normalize(objectPosition - cameraPosition));

    // If the dot product is less than .0, the object is behind the camera
    if (dotProduct < 0)
    {
        return false;
    }

    // If the distance is greater than the far plane, the object is too far away
    if (distance > farPlane)
    {
        return false;
    }

    // Otherwise, the object is visible
    return true;
}

