    for (auto& object : objects) {
        glUseProgram(object.shaderProgram);
        glBindVertexArray(object.vao);
        glUniformMatrix4fv(glGetUniformLocation(object.shaderProgram, "model"), 1, GL_FALSE, glm::value_ptr(object.modelMatrix));
        glDrawElements(GL_TRIANGLES, object.indices.size(), GL_UNSIGNED_INT, (void*)0);
    }
}
```

#### Optimized Code (Using Instancing)

1. **Create a Texture Atlas**: Combine multiple textures into a single atlas.
2. **Use Instancing**: Render multiple instances of the same object with a single draw call.

```cpp
// Assume we have a texture atlas and a single shader program
GLuint textureAtlas;
GLuint shaderProgram;

struct InstanceData {
    glm::mat4 modelMatrix;
};

std::vector<InstanceData> instanceData;

void setupInstancing() {
    glGenBuffers(1, &instanceBuffer);
    glBindBuffer(GL_ARRAY_BUFFER, instanceBuffer);
    glBufferData(GL_ARRAY_BUFFER, instanceData.size() * sizeof(InstanceData), instanceData.data(), GL_STATIC_DRAW);

    GLuint instanceAttribLocation = glGetAttribLocation(shaderProgram, "instanceModel");
    glEnableVertexAttribArray(instanceAttribLocation);
    glVertexAttribPointer(instanceAttribLocation, 4, GL_FLOAT, GL_FALSE, sizeof(InstanceData), (void*)0);
    glVertexAttribDivisor(instanceAttribLocation, 1); // Divisor 1 means per-instance attribute

    glEnableVertexAttribArray(instanceAttribLocation + 1);
    glVertexAttribPointer(instanceAttribLocation + 1, 4, GL_FLOAT, GL_FALSE, sizeof(InstanceData), (void*)(sizeof(glm::vec4)));
    glVertexAttribDivisor(instanceAttribLocation + 1, 1);

    glEnableVertexAttribArray(instanceAttribLocation + 2);
    glVertexAttribPointer(instanceAttribLocation + 2, 4, GL_FLOAT, GL_FALSE, sizeof(InstanceData), (void*)(2 * sizeof(glm::vec4)));
    glVertexAttribDivisor(instanceAttribLocation + 2,  1);

    glEnableVertexAttribArray(instanceAttribLocation + 3);
    glVertexAttribPointer(instanceAttribLocation + 3, 4, GL_FLOAT, GL_FALSE, sizeof(InstanceData), (void*)(3 * sizeof(glm::vec4)));
    glVertexAttribDivisor(instanceAttribLocation + 3, 1);
}

void renderScene() {
    glUseProgram(shaderProgram);
    glBindVertexArray(vao);

    // Bind the texture atlas
    glActiveTexture(GL_TEXTURE0);
    glBindTexture(GL_TEXTURE_2D, textureAtlas);

    // Set the number of instances
    glDrawElementsInstanced(GL_TRIANGLES, indices.size(), GL_UNSIGNED_INT, (void*)0, instanceData.size());
}
```

### Explanation

