    {
        FScopeLock Lock(&CriticalSection);
        if (!LogBuffer.IsEmpty())
        {
            FFileHelper::SaveStringArrayToFile(LogBuffer, *LogFile, FFileHelper::EEncodingOptions::AutoDetect);
            LogBuffer.Empty();
            CurrentBufferSize = 0;
        }
    }

    FString LogFile;
    int32 BufferSize;
    int32 CurrentBufferSize;
    TArray<FString> LogBuffer;
    FCriticalSection CriticalSection;
};

