#include <iostream>
#include <fstream>
#include <filesystem>
#include <chrono>
#include <thread>

namespace fs = std::filesystem;

void rotate_log(const std::string& log_path, size_t max_size) {
    if (fs::exists(log_path)) {
        auto file_size = fs::file_size(log_path);
        if (file_size > max_size) {
            std::string new_log_path = log_path + "." + std::to_string(std::chrono::system_clock::now().time_since_epoch().count());
            fs::rename(log_path, new_log_path);
        }
    }
}

int main() {
