void ARoadSpline::LoadSplineData()
{
    const int NumPoints = 100000;  // Number of spline points
    TArray<void*> SplineData;

    for (int i = 0; i < NumPoints; ++i)
    {
        float* Point = (float*)MemoryPool->Allocate(sizeof(float) * 3);
        Point[0] = static_cast<float>(i);
        Point[1] = static_cast<float>(i * 2);
        Point[2] = static_cast<float>(i * 3);
        SplineData.Add(Point);
    }

    // Simulate some processing time
    FPlatformProcess::Sleep(1.0f);

    // Deallocate memory when done
    for (void* Point : SplineData)
    {
        MemoryPool->Deallocate(Point);
    }
}
