void URoadLODManagerComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    APlayerController* PlayerController = GetWorld()->GetFirstPlayerController();
    if (PlayerController)
    {
        FVector CameraLocation = PlayerController->GetPawn()->GetActorLocation();
        float Distance = (CameraLocation - GetOwner()->GetActorLocation()).Size();

        SwitchLOD(Distance);
    }
