    if (Distance > LODDistances[1])
    {
        LODIndex = 2;
    }
    else if (Distance > LODDistances[0])
    {
        LODIndex = 1;
    }

    for (int i = 0; i < LODMeshes.Num(); ++i)
    {
        LODMeshes[i]->SetVisibility(i == LODIndex);
