class ComponentRegistry:
    def __init__(self):
        self.components = {}

    def register_component(self, name, component):
        self.components[name] = component

    def get_component(self, name):
        return self.components.get(name)

class Component(ABC):
    @abstractmethod
    def version(self):
        pass

    @abstractmethod
    def swap(self, new_component):
        pass

