        // Signal the logging thread to exit
        {
            std::lock_guard<std::mutex> lock(LogQueueMutex);
            Shutdown = true;
        }
        LogQueueCondition.notify_one();
        AsyncLoggingThread.join();
    }

    void Log(const FString& message)
    {
        std::lock_guard<std::mutex> lock(LogQueueMutex);
        LogQueue.push(message);
        LogQueueCondition.notify_one();
    }

private:
    std::thread AsyncLoggingThread;
    std::queue<FString> LogQueue;
    std::mutex LogQueueMutex;
    std::condition_variable LogQueueCondition;
    bool Shutdown = false;
};

IMPLEMENT_MODULE(FMyPlugin, MyPlugin)
```

